/* Flash cards USMLE: Reproductive (415 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["reproductive"] = [{"name":"Anatomy","cards":[["g03yco19h","What does the infundibulopelvic (suspensory) ligament of the ovary contain?","Ovarian vessels; ligated in oophorectomy, at risk of ureteral injury.","Vasos ovarianos."],["1natyob10","What does the cardinal ligament contain?","Uterine vessels; ligated in hysterectomy; ureter at risk.","Vasos uterinos."],["3y5akg1o0","What is the round ligament of the uterus?","Derivative of gubernaculum; passes through inguinal canal to labia majora; contains artery of Sampson.","Passa pelo canal inguinal."],["18a0aq7tk","What does the broad ligament contain?","Ovaries, fallopian tubes, round ligaments (mesosalpinx, mesovarium, mesometrium).","Ovários, trompas e ligamento redondo."],["tab1zrbh3","What does the ovarian ligament connect?","Ovary to the lateral uterus (derivative of gubernaculum).","Liga ovário ao útero."],["lkju01463","What is the histology of the vagina?","Stratified squamous epithelium, nonkeratinized.","Epitélio escamoso não queratinizado."],["461rfzvwn","What is the histology of the ectocervix vs endocervix?","Ectocervix: stratified squamous nonkeratinized. Endocervix: simple columnar.","Ectocérvice escamosa; endocérvice colunar."],["1ecndnjol","What is the transformation zone of the cervix?","Squamocolumnar junction; most common site of cervical cancer (HPV).","Junção escamocolunar."],["olo547qe4","What is the histology of the uterus?","Endometrium: simple columnar with tubular glands; myometrium: smooth muscle.","Endométrio e miométrio."],["t8y2ofmk1","What is the histology of the fallopian tube?","Simple columnar epithelium with ciliated cells.","Epitélio colunar ciliado."],["1ug52v8ky","What is the histology of the ovary?","Simple cuboidal germinal epithelium (surface); stroma with follicles.","Epitélio cúbico."],["15rnudt1d","What is the lymphatic drainage of the ovaries and testes?","Para-aortic lymph nodes.","Para-aórticos."],["1xe90kz12","What is the lymphatic drainage of the uterus, cervix, and upper vagina?","Obturator, external iliac, hypogastric nodes.","Ilíacos e obturatórios."],["wqq47dw4m","What is the lymphatic drainage of the lower vagina and vulva?","Superficial inguinal nodes.","Inguinais superficiais."],["djqw2hq5r","What is the lymphatic drainage of the glans penis?","Deep inguinal nodes.","Inguinais profundos."],["1i52b811b","What is the arterial supply of the ovaries?","Ovarian arteries from the abdominal aorta.","Artérias ovarianas da aorta."],["aojzaszat","What is the arterial supply of the uterus?","Uterine arteries from the internal iliac arteries.","Artérias uterinas."],["1g545oko9","What is the arterial supply of the testes?","Testicular arteries from the abdominal aorta.","Artérias testiculares."],["102eq431q","What is the venous drainage of the left vs right gonadal veins?","Left: left renal vein. Right: IVC.","Esquerda para renal; direita para cava."],["pwtaz21gv","What is the path of sperm?","Seminiferous tubules, rete testis, efferent ductules, epididymis, vas deferens, ejaculatory ducts, (nothing) urethra, penis (SEVEN UP).","Caminho do espermatozoide."],["inum75l4j","What is the role of Sertoli cells?","Secrete inhibin B (inhibits FSH), androgen-binding protein, Müllerian inhibitory factor; form blood-testis barrier (tight junctions); support spermatogenesis; regulated by FSH.","Barreira, inibina, suporte."],["1q339fl16","What is the role of Leydig cells?","Secrete testosterone in response to LH; interstitial cells.","Produzem testosterona."],["l2cu45407","Why are Leydig cells less affected by temperature than Sertoli cells?","Sertoli cells and spermatogenesis are temperature sensitive; Leydig cells are not (cryptorchidism impairs spermatogenesis but testosterone can be normal).","Sertoli sensível ao calor."],["abyxjj14k","What is the blood-testis barrier's purpose?","Isolates gametes from autoimmune attack.","Protege os gametas do sistema imune."],["ilrrs61on","What are the parts of the male erection, emission, and ejaculation autonomic control?","Erection: parasympathetic (pelvic splanchnic, NO). Emission: sympathetic (hypogastric). Ejaculation: visceral and somatic (pudendal). Point, Squeeze, Shoot.","Parassimpático, simpático, somático."],["wkz49m1pq","What is the pudendal nerve's role?","Sensation to perineum and genitalia; motor to external urethral and anal sphincters.","Sensibilidade do períneo e esfíncteres."],["1qaropod8","Where is the pudendal nerve blocked for labor?","Ischial spine (landmark).","Espinha isquiática."],["qgagej1kj","What is the corpus luteum?","Remnant of ovulated follicle producing progesterone (and estrogen) under LH; regresses without hCG.","Produz progesterona."],["1yeqfco1k","What are the zones of the prostate?","Peripheral (most prostate cancers), transition (BPH), central.","Periférica: câncer; transição: hiperplasia."],["q1dw9r10f","Why is prostate cancer detected by digital rectal exam?","Most arise in the posterior peripheral zone.","Zona periférica posterior."],["13o458w16","What forms the spermatic cord?","Vas deferens, testicular artery and vein (pampiniform plexus), cremasteric artery, lymphatics, genital branch of genitofemoral nerve.","Componentes do cordão espermático."],["1hy20mcwu","What is the role of the pampiniform plexus?","Cools arterial blood to the testes (countercurrent heat exchange).","Esfria o sangue."],["7s61xapbp","What is the role of the cremaster muscle?","Elevates testis (cremasteric reflex, genitofemoral nerve).","Eleva o testículo."],["mnhwaf1u7","What is the tunica vaginalis?","Serous covering of the testis from processus vaginalis; site of hydroceles.","Túnica vaginal."],["1n9kyrtk4","What is the tunica albuginea?","Dense fibrous capsule around testis and corpora cavernosa.","Cápsula fibrosa."],["1xejakqts","What are the parts of the penis?","Two corpora cavernosa and one corpus spongiosum (containing urethra).","Corpos cavernosos e esponjoso."],["xq86jo1kl","What is the location of the Bartholin glands?","Posterolateral to the vaginal orifice; obstruction causes cyst or abscess.","Lateral ao orifício vaginal."],["fwotbw17c","What is the pouch of Douglas?","Rectouterine pouch; lowest point of the peritoneal cavity in females (fluid collects).","Fundo de saco de Douglas."],["1btii3vsc","What is culdocentesis?","Needle aspiration of the rectouterine pouch through posterior vaginal fornix.","Punção do fundo de saco."],["16xjq4v47","What is the location of the ovaries relative to the ureters?","Ureters run posterior to the ovaries along the pelvic sidewall.","Ureteres atrás dos ovários."],["uimsm5ox2","What is the location of the internal iliac artery's uterine branch relative to the ureter?","Uterine artery crosses above the ureter (water under the bridge).","Artéria passa sobre o ureter."],["1hz58b7r1","What are the parts of the fallopian tube?","Infundibulum (fimbriae), ampulla (fertilization, ectopic site), isthmus, intramural part.","Infundíbulo, ampola, istmo."],["1lxuhqkd0","What is the histology of the epididymis?","Pseudostratified columnar epithelium with stereocilia.","Pseudoestratificado com estereocílios."],["14ildtnzt","What is the histology of the vas deferens?","Pseudostratified columnar epithelium with thick smooth muscle.","Músculo liso espesso."],["1xwh7u1k4","What do seminal vesicles secrete?","Fructose-rich fluid (energy for sperm), prostaglandins, semenogelin.","Frutose."],["973tfh1n1","What does the prostate secrete?","Alkaline fluid, PSA (liquefies semen), zinc, citric acid.","PSA e fluido alcalino."],["1bnmlxo13","What do bulbourethral glands secrete?","Mucus to lubricate the urethra and neutralize acidity.","Muco lubrificante."],["taivow1vj","What is the pelvic floor's main muscle?","Levator ani (pubococcygeus, iliococcygeus, puborectalis).","Elevador do ânus."],["1lmd9ey19","What is uterine prolapse associated with?","Pelvic floor weakness (multiparity, aging, obesity).","Fraqueza do assoalho pélvico."],["1ko3qb7vf","What is a cystocele vs rectocele?","Cystocele: bladder herniates into anterior vaginal wall. Rectocele: rectum into posterior wall.","Bexiga ou reto na vagina."],["w5h5xj126","What is the anatomic landmark for the uterine artery during hysterectomy?","Ureter passes under the uterine artery near the cervix.","Ureter sob a artéria uterina."],["dsvh4l1dt","What nerve gives sensation to the anterior scrotum and labia?","Ilioinguinal nerve.","Nervo ilioinguinal."],["igbvditlz","What nerve gives sensation to the posterior scrotum and labia?","Pudendal nerve.","Nervo pudendo."],["pvt0txdty","What is the location of the testes descent and final position timeline?","Descend through inguinal canal by third trimester; usually in scrotum by birth or within 6 months.","Descem até o nascimento."],["1ru56jjgc","What is the cause of testicular torsion?","Bell-clapper deformity (inadequate attachment of testis to tunica vaginalis), twisting of spermatic cord.","Deformidade em badalo de sino."],["16eqoef1a","What is the clinical presentation of testicular torsion?","Sudden severe testicular pain, high-riding horizontal testis, absent cremasteric reflex; surgical emergency.","Dor súbita e reflexo cremastérico ausente."],["1q53b1u18","What is the role of the gubernaculum in males and females?","Males: anchors testes in scrotum. Females: ovarian ligament and round ligament.","Ancoragem do testículo; ligamentos no útero."],["aahh7yy1c","What is the histologic hallmark of mature ovarian follicles?","Graafian follicle with antrum, granulosa cells, theca cells.","Folículo de Graaf."],["101t8rr15","What is the two-cell theory of estrogen synthesis?","Theca cells (LH) make androstenedione; granulosa cells (FSH) convert it to estradiol via aromatase.","Teca e granulosa."],["4gzx7273m","What is the anatomic site for most ectopic pregnancies?","Ampulla of the fallopian tube.","Ampola da trompa."]]},{"name":"Pathology (Part 1)","cards":[["e8759q19v","What is polycystic ovarian syndrome?","Hyperandrogenism, oligo/anovulation, polycystic ovaries; insulin resistance, obesity, acanthosis nigricans; increased endometrial cancer risk.","SOP: hiperandrogenismo e anovulação."],["r1fq6w1tb","Treatment of PCOS?","Weight loss, OCPs (regulate cycle, reduce androgens), spironolactone, metformin, letrozole or clomiphene for fertility.","Perda de peso, anticoncepcional, letrozol."],["xfbhff15n","Why does PCOS increase endometrial cancer risk?","Unopposed estrogen due to anovulation (no progesterone).","Estrogênio sem oposição."],["fuhnajkgy","What is endometriosis?","Endometrial glands and stroma outside the uterus (ovary: chocolate cyst; pelvis, peritoneum): dysmenorrhea, dyspareunia, dyschezia, infertility.","Endométrio fora do útero."],["c3r1au1by","Treatment of endometriosis?","NSAIDs, OCPs, progestins, GnRH agonists or antagonists, danazol, laparoscopic excision.","Anticoncepcional, progestágeno, cirurgia."],["m50n2xyib","What is adenomyosis?","Endometrial tissue within the myometrium: dysmenorrhea, menorrhagia, uniformly enlarged boggy uterus.","Endométrio no miométrio; útero globoso."],["1fj05m8g4","What is endometrial hyperplasia?","Abnormal endometrial gland proliferation from unopposed estrogen: postmenopausal bleeding; atypia increases cancer risk.","Proliferação por estrogênio sem oposição."],["1ij7btb1w","What is a leiomyoma (fibroid)?","Most common benign uterine tumor (estrogen-sensitive), more common in Black women; whorled pattern; menorrhagia, pelvic pressure, infertility; shrink after menopause.","Mioma uterino."],["lcskknj7a","Treatment of symptomatic fibroids?","GnRH agonists, progestins, tranexamic acid, uterine artery embolization, myomectomy, hysterectomy.","Embolização ou cirurgia."],["18xu4t7cl","What is an ovarian torsion?","Twisting of ovary and fallopian tube (often with mass): acute severe pelvic pain, nausea; surgical emergency.","Torção do ovário."],["1yvf9q7qq","What is a follicular cyst?","Distension of unruptured graafian follicle; most common ovarian mass in young women; may produce estrogen.","Cisto folicular."],["1qc11wi1k","What is a theca lutein cyst?","Bilateral cysts from hCG stimulation (molar pregnancy, multiple gestation, choriocarcinoma).","Cistos por hCG alto."],["1hmhdu61g","What is a corpus luteum cyst?","Hemorrhage into corpus luteum; can rupture causing hemoperitoneum.","Cisto do corpo lúteo."],["1qzl53y14","What is pelvic inflammatory disease?","Ascending infection (Chlamydia, gonorrhea): cervical motion tenderness, adnexal tenderness, fever, purulent discharge; complications infertility, ectopic, tubo-ovarian abscess.","DIP."],["1f2q2vo4r","What is ectopic pregnancy's presentation?","Amenorrhea, lower abdominal pain, vaginal bleeding; hCG lower than expected; risk of rupture with hemorrhagic shock.","Dor, sangramento e hCG baixo."],["uvzwizlwi","Treatment of ectopic pregnancy?","Methotrexate (stable, small, no fetal heart activity) or surgery (salpingostomy/salpingectomy).","Metotrexato ou cirurgia."],["18e1h7h1i","What is spontaneous abortion?","Pregnancy loss before 20 weeks; most often from chromosomal abnormalities in the first trimester.","Aborto espontâneo."],["1edipxb1c","What are the types of abortion?","Threatened (closed os, viable), inevitable (open os, no tissue passed), incomplete (some tissue passed), complete, missed (nonviable, closed os).","Tipos de aborto."],["14eblsr83","What are causes of recurrent pregnancy loss?","Antiphospholipid syndrome, chromosomal translocations, uterine anomalies (septate uterus), endocrine disorders.","Antifosfolípide e anomalias."],["11lqchfqy","What is placenta previa?","Placenta over the internal os: painless bright red vaginal bleeding in third trimester; avoid digital exam.","Sangramento indolor."],["no2lhq18d","What is placental abruption?","Premature separation of placenta: painful vaginal bleeding, uterine tenderness, fetal distress, DIC; risk factors hypertension, cocaine, trauma, smoking.","Sangramento doloroso."],["1mesal21i","What is vasa previa?","Fetal vessels over the internal os; painless bleeding with rupture of membranes and fetal bradycardia; high fetal mortality.","Vasos fetais sobre o colo."],["12qjwrjck","What is uterine rupture?","Loss of uterine wall integrity (prior C-section): abdominal pain, loss of fetal station, fetal distress.","Ruptura uterina."],["1mk4kckbu","What is postpartum hemorrhage's most common cause?","Uterine atony (4 Ts: tone, trauma, tissue, thrombin).","Atonia uterina."],["a84yj21hx","Treatment of uterine atony?","Uterine massage, oxytocin, methylergonovine, carboprost, misoprostol, tranexamic acid; surgery if refractory.","Massagem e ocitocina."],["14q9wg77h","When is methylergonovine contraindicated?","Hypertension (preeclampsia).","Hipertensão."],["1efprcr17","When is carboprost contraindicated?","Asthma (bronchoconstriction).","Asma."],["1e44gi5i8","What is gestational hypertension?","BP ≥140/90 after 20 weeks without proteinuria or end-organ damage.","Hipertensão após 20 semanas."],["1vu4ku81v","What is preeclampsia?","New hypertension after 20 weeks with proteinuria or end-organ dysfunction; abnormal placental spiral arteries cause endothelial dysfunction.","Hipertensão com proteinúria."],["b3prao1vw","What are severe features of preeclampsia?","BP ≥160/110, thrombocytopenia, elevated liver enzymes, renal insufficiency, pulmonary edema, headache, visual disturbances.","Sinais de gravidade."],["a0yqu514k","Treatment of preeclampsia?","Delivery (definitive), antihypertensives (labetalol, hydralazine, nifedipine), magnesium sulfate for seizure prophylaxis.","Parto e sulfato de magnésio."],["1v0gpdztt","What is eclampsia?","Preeclampsia with seizures; treat with magnesium sulfate and delivery.","Pré-eclâmpsia com convulsões."],["kh1mg2v9q","What is HELLP syndrome?","Hemolysis, Elevated Liver enzymes, Low Platelets; variant of severe preeclampsia; risk of hepatic hematoma rupture.","Hemólise, enzimas hepáticas, plaquetas baixas."],["eo92kgqrx","What are signs of magnesium toxicity?","Loss of deep tendon reflexes, respiratory depression, cardiac arrest; treat with calcium gluconate.","Perda de reflexos; gluconato de cálcio."],["m1w7lk14y","What is the prophylaxis for preeclampsia in high-risk women?","Low-dose aspirin starting at 12 weeks.","Aspirina em dose baixa."],["fvs2gm86k","What is gestational diabetes?","Glucose intolerance in pregnancy (screened at 24-28 weeks); risks: macrosomia, shoulder dystocia, neonatal hypoglycemia; treat with diet, insulin, metformin.","Diabetes na gestação."],["gldfyc129","What is acute fatty liver of pregnancy?","Microvesicular fatty liver in third trimester: liver failure, hypoglycemia, coagulopathy; fetal LCHAD deficiency.","Fígado gorduroso agudo."],["k3cswo1fp","What is intrahepatic cholestasis of pregnancy?","Pruritus (palms and soles) and elevated bile acids in third trimester; fetal risk; treat with ursodiol.","Coceira e ácidos biliares altos."],["1gyy6qk1l","What is hyperemesis gravidarum?","Severe vomiting in pregnancy causing weight loss, dehydration, electrolyte imbalance; associated with high hCG (molar, multiple).","Vômitos graves na gestação."],["18n7a4jq5","What is Sheehan syndrome?","Postpartum pituitary infarction after hemorrhage: agalactorrhea, amenorrhea, hypothyroidism, adrenal insufficiency.","Necrose da hipófise após hemorragia."],["c3imiv1dx","What is preterm labor and its management?","Contractions with cervical change before 37 weeks: tocolytics (nifedipine, indomethacin), corticosteroids (betamethasone), magnesium for neuroprotection (<32 weeks), GBS prophylaxis.","Corticoide e tocolíticos."],["l9am0j1i4","What is premature rupture of membranes?","Rupture before labor; risk of chorioamnionitis; diagnosed with nitrazine (blue) and fern test.","Ruptura prematura de membranas."],["qfval3g4k","What is chorioamnionitis?","Infection of amniotic fluid and membranes: maternal fever, tachycardia, uterine tenderness, foul fluid; treat with antibiotics and delivery.","Infecção amniótica."],["1gc9qga18","What is oligohydramnios associated with?","Placental insufficiency, bilateral renal agenesis, posterior urethral valves, ruptured membranes; causes Potter sequence.","Pouco líquido amniótico."],["1os6apum4","What is polyhydramnios associated with?","Maternal diabetes, fetal GI atresia, anencephaly, multiple gestation.","Excesso de líquido amniótico."],["s90gxcpo7","What is a hydatidiform mole's presentation?","Vaginal bleeding, uterus larger than dates, very high hCG, hyperemesis, early preeclampsia, theca lutein cysts, snowstorm on ultrasound.","hCG muito alto e útero grande."],["1ytcnfx1x","What is choriocarcinoma?","Malignant trophoblastic tumor (no chorionic villi): very high hCG, hematogenous spread to lungs (cannonball metastases); after molar pregnancy, abortion, or normal pregnancy; responsive to methotrexate.","Tumor trofoblástico maligno."],["1dyqu571o","What is the most common cause of primary amenorrhea?","Turner syndrome.","Síndrome de Turner."],["17vdwmj1t","What is Müllerian agenesis?","46,XX, absent uterus and upper vagina, normal ovaries and secondary sexual characteristics.","Ausência de útero com ovários normais."],["1v3yr2v1c","What is imperforate hymen's presentation?","Primary amenorrhea with cyclic pelvic pain and bulging bluish membrane (hematocolpos).","Amenorreia com dor cíclica."],["fa1pcx15q","What is dysmenorrhea?","Painful menses; primary due to prostaglandins (treat with NSAIDs); secondary due to endometriosis, adenomyosis, fibroids.","Cólica menstrual."],["mesteur20","What is abnormal uterine bleeding's classification?","PALM-COEIN: Polyp, Adenomyosis, Leiomyoma, Malignancy; Coagulopathy, Ovulatory dysfunction, Endometrial, Iatrogenic, Not classified.","Classificação PALM-COEIN."],["wtdpal1se","What is the evaluation of postmenopausal bleeding?","Transvaginal ultrasound (endometrial thickness) and/or endometrial biopsy to rule out endometrial cancer.","Ultrassom e biópsia endometrial."],["1lj1j30xe","What is bacterial vaginosis?","Gardnerella overgrowth: thin gray discharge, fishy odor (positive whiff test), clue cells, pH >4.5; no inflammation.","Vaginose bacteriana."],["afx5cy1ta","What is vulvovaginal candidiasis?","Thick white cottage cheese discharge, pruritus, normal pH, pseudohyphae on KOH.","Candidíase vulvovaginal."],["1hsbjbgdz","What is trichomoniasis?","Frothy yellow-green discharge, strawberry cervix, motile trophozoites, pH >4.5.","Tricomoníase."],["2ayqdcv8j","What is atrophic vaginitis?","Postmenopausal thin vaginal epithelium from estrogen deficiency: dryness, dyspareunia; treat with topical estrogen.","Atrofia por falta de estrogênio."],["1kap0661m","What is lichen sclerosus?","Thin, white parchment-like vulvar skin in postmenopausal women; slight increase in squamous cell carcinoma risk.","Pele vulvar branca e fina."],["17952ml1b","What is lichen simplex chronicus?","Thickened vulvar skin from chronic rubbing; not premalignant.","Espessamento por coçar."],["wu3lz3haw","What is a Bartholin cyst?","Cyst from obstructed Bartholin duct; abscess if infected; treat with drainage.","Cisto de Bartholin."],["edvhti1wx","What is gynecomastia's causes?","Puberty, aging, cirrhosis, hyperthyroidism, Klinefelter, drugs (spironolactone, ketoconazole, cimetidine, digoxin, marijuana), testicular tumors.","Causas de ginecomastia."],["1m7fu4m2i","What is mastitis?","Breast infection during breastfeeding (S. aureus); continue breastfeeding; treat with dicloxacillin.","Mastite; manter amamentação."],["1fxyyx2nb","What is fat necrosis of the breast?","Benign painless mass after trauma, calcifications; mimics carcinoma.","Necrose gordurosa após trauma."],["1sragvfl7","What is fibrocystic change?","Diffuse breast pain and lumpiness varying with menstrual cycle; common, benign.","Alterações fibrocísticas."],["1v4jygnqj","What is fibroadenoma?","Most common benign breast tumor in women <35: small, mobile, firm, well-circumscribed; increases with estrogen.","Nódulo móvel em jovens."],["wecbu277s","What is intraductal papilloma?","Benign tumor of lactiferous ducts causing serous or bloody nipple discharge.","Descarga mamilar sanguinolenta."],["1xm5wdj1m","What is phyllodes tumor?","Large bulky mass of connective tissue with leaf-like projections; older women; can be malignant.","Tumor filoides."],["1a61fxw1e","What is the most common cause of breast mass in adolescents?","Fibroadenoma.","Fibroadenoma."],["1ne3mrl7o","What is the evaluation of a breast mass in a woman younger than 30?","Ultrasound first.","Ultrassom."],["id7n9j1rk","What is the evaluation of a breast mass in a woman aged 30 or older?","Diagnostic mammogram plus ultrasound; biopsy if suspicious.","Mamografia e ultrassom."],["1svvkp2gp","What is benign prostatic hyperplasia?","Hyperplasia of the transitional zone (DHT-driven): urinary frequency, nocturia, weak stream, retention, UTIs, hydronephrosis.","Hiperplasia da zona de transição."],["1p2ylu5y9","Treatment of BPH?","Alpha1 blockers (tamsulosin), 5-alpha-reductase inhibitors (finasteride), PDE5 inhibitors (tadalafil), TURP.","Tansulosina e finasterida."],["qdpf6a1uk","What is prostatitis?","Acute: fever, dysuria, tender prostate (E. coli, or STI in young). Chronic: pelvic pain.","Prostatite."],["n67qq615j","What is cryptorchidism's risks?","Infertility, testicular germ cell tumors (seminoma); orchiopexy by 1 year (reduces infertility but not fully cancer risk).","Infertilidade e câncer."],["1vxqtwl17","What is varicocele?","Dilated pampiniform plexus (left more common): bag of worms, worse standing; infertility; does not transilluminate.","Varicocele."],["1kh25d91x","What is hydrocele?","Fluid collection in tunica vaginalis; transilluminates.","Hidrocele; transilumina."],["146fs1ynd","What is spermatocele?","Cyst of the epididymis containing sperm; transilluminates.","Cisto com espermatozoides."],["1y7hyyu13","What is epididymitis's causes and features?","Young men: Chlamydia, gonorrhea; older: E. coli; localized pain, positive Prehn sign (relief with elevation), intact cremasteric reflex.","Dor que melhora ao elevar o testículo."],["6vxcxv1gt","What is orchitis's common cause?","Mumps (bilateral, may cause infertility).","Caxumba."],["1uwsal1zy","What is Peyronie disease?","Fibrous plaque in tunica albuginea causing penile curvature and painful erections.","Curvatura peniana."],["iwrofk167","What is priapism and its causes?","Painful prolonged erection >4 hours: sickle cell disease, trazodone, PDE5 inhibitors, intracavernosal drugs.","Ereção prolongada dolorosa."],["1x6e0lp1t","What is phimosis vs paraphimosis?","Phimosis: inability to retract foreskin. Paraphimosis: retracted foreskin that cannot return (emergency).","Fimose e parafimose."],["ikomdijwr","What is the most common cause of postpartum fever?","Endometritis (polymicrobial, after C-section); treat with clindamycin plus gentamicin.","Endometrite."],["1myxdjj1v","What is postpartum thyroiditis?","Painless thyroiditis within a year of delivery; hyperthyroid then hypothyroid phase.","Tireoidite pós-parto."],["82ax382mb","What is Rh alloimmunization prevention?","Anti-D immunoglobulin at 28 weeks, after delivery (if baby Rh+), and after bleeding or procedures.","Imunoglobulina anti-D."],["h7hretcun","What is the screening for group B strep in pregnancy?","Rectovaginal culture at 36-37 weeks; intrapartum penicillin if positive.","Cultura com 36 semanas."],["g9chlkilv","What is the screening for gestational diabetes?","Glucose challenge test at 24-28 weeks (earlier if high risk).","Teste com 24 a 28 semanas."],["1ct69vtw3","What is the triple or quad screen used for?","Second-trimester screening for neural tube defects and aneuploidy.","Rastreio no segundo trimestre."],["zg6lfh1km","What is the cause of infertility with normal ovulation and semen analysis?","Tubal factor (prior PID, endometriosis); assess with hysterosalpingography.","Fator tubário."],["jm6tc2zid","What is ovarian hyperstimulation syndrome?","Complication of fertility treatment with ovarian enlargement, ascites, fluid shifts, thrombosis.","Complicação de indução da ovulação."],["ymlmlj5rv","What is the cause of hirsutism with rapid virilization?","Androgen-secreting tumor (ovarian Sertoli-Leydig tumor or adrenal tumor); check DHEA-S and testosterone.","Tumor produtor de androgênio."],["141ffbs1d","What is the cause of hirsutism with high 17-hydroxyprogesterone?","Nonclassic congenital adrenal hyperplasia.","Hiperplasia adrenal não clássica."],["7mo5ya1xj","What is the cause of pelvic pain with fever and an adnexal mass after PID?","Tubo-ovarian abscess.","Abscesso tubo-ovariano."],["1254n7o1l","What is Fitz-Hugh-Curtis syndrome's presentation?","RUQ pain from perihepatitis with PID.","Dor no hipocôndrio direito na DIP."],["1jowvtm2w","What is the leading cause of maternal death worldwide?","Postpartum hemorrhage (and hypertensive disorders, sepsis).","Hemorragia pós-parto."],["15ptayn12","What is the leading cause of maternal death in the US?","Cardiovascular disease (cardiomyopathy), hemorrhage, hypertensive disorders, mental health conditions.","Doença cardiovascular."],["him9i41fn","What is amniotic fluid embolism?","Sudden hypoxia, hypotension, DIC during labor or shortly after; high mortality.","Embolia de líquido amniótico."],["11igeo34w","What is shoulder dystocia's risk factors?","Macrosomia, maternal diabetes, obesity; brachial plexus injury (Erb palsy).","Macrossomia e diabetes."],["rt1eaz1wa","What is the cause of an enlarged uterus with irregular contour?","Leiomyomas.","Miomas."],["1jbg2cg1s","What is the cause of an enlarged uterus that is uniformly boggy?","Adenomyosis.","Adenomiose."],["u1jv6s16y","What is the cause of cyclic pelvic pain, dyspareunia, and infertility?","Endometriosis.","Endometriose."],["1wyjzvn8a","What is the cause of pelvic pain with positive hCG and empty uterus?","Ectopic pregnancy.","Gravidez ectópica."],["d1z5nqq0j","What is the cause of first-trimester vaginal bleeding with snowstorm ultrasound?","Complete hydatidiform mole.","Mola completa."]]},{"name":"Pathology (Part 2)","cards":[["pjgzsyroo","What is cervical dysplasia (CIN)?","Disordered epithelial growth from HPV (16, 18) at the transformation zone: CIN 1 (lower third), CIN 2 (two thirds), CIN 3 (full thickness, carcinoma in situ).","Displasia cervical por HPV."],["11k1epp1q","What are risk factors for cervical cancer?","HPV (16, 18), multiple partners, smoking, early sexual activity, immunosuppression (HIV).","HPV, tabagismo, HIV."],["1r2vwgnmu","What is the most common type of cervical cancer?","Squamous cell carcinoma (adenocarcinoma second).","Carcinoma escamoso."],["3zhwg2u9o","How does invasive cervical cancer present and spread?","Postcoital bleeding, discharge; lateral invasion blocks ureters (hydronephrosis, renal failure).","Sangramento pós-coito; obstrução ureteral."],["1x3270nx9","What is the cervical cancer screening schedule?","Pap smear every 3 years ages 21-29; ages 30-65 Pap every 3 years, HPV test every 5 years, or cotesting every 5 years.","Rastreio do colo do útero."],["1kz694djv","What is the HPV vaccine schedule?","Routinely at 11-12 years (2 doses if before 15); up to 26 years, shared decision 27-45.","Vacina aos 11-12 anos."],["1i25d6p1t","What is the most common gynecologic malignancy in the US?","Endometrial carcinoma.","Câncer de endométrio."],["11b8ctf1u","What is the type 1 (endometrioid) endometrial carcinoma?","Estrogen-dependent, from endometrial hyperplasia, in perimenopausal women; risk factors obesity, nulliparity, PCOS, tamoxifen, early menarche, late menopause.","Estrogênio-dependente."],["14kkvs8na","What is the type 2 (serous) endometrial carcinoma?","Not estrogen-related, older thin women, from atrophic endometrium; p53 mutation, psammoma bodies; aggressive.","Seroso, agressivo, p53."],["1thqwumon","What is the presentation of endometrial cancer?","Postmenopausal vaginal bleeding.","Sangramento pós-menopausa."],["z1wefjj4y","What is the hereditary syndrome associated with endometrial cancer?","Lynch syndrome.","Síndrome de Lynch."],["xv8ept1cj","What is the protective factor for endometrial and ovarian cancer?","Combined oral contraceptives (and multiparity, breastfeeding for ovarian).","Anticoncepcional oral."],["ueb6hqp4p","What is leiomyosarcoma?","Malignant smooth muscle tumor of the uterus, arises de novo (not from leiomyoma); postmenopausal women; bulky irregular mass with necrosis.","Sarcoma uterino."],["yj1fv115y","What are the risk factors for ovarian cancer?","BRCA1/2, Lynch syndrome, age, infertility, endometriosis, nulliparity, early menarche/late menopause.","BRCA e nuliparidade."],["ibi9z05fv","What tumor marker is used for epithelial ovarian cancer?","CA-125 (monitoring; not for screening general population).","CA-125."],["1dcw1vir0","What is the most common ovarian tumor type?","Surface epithelial tumors (serous most common).","Tumores epiteliais."],["1puq58718","What is serous cystadenoma?","Benign ovarian tumor lined with fallopian tube-like epithelium, often bilateral.","Cistoadenoma seroso benigno."],["1oxjupft8","What is serous carcinoma of the ovary?","Most common malignant ovarian tumor; psammoma bodies; BRCA association; arises from fallopian tube epithelium.","Carcinoma seroso."],["jrlm1b15g","What is mucinous cystadenoma?","Benign multiloculated large ovarian tumor lined by mucus-secreting epithelium.","Cistoadenoma mucinoso."],["rd4i22183","What is pseudomyxoma peritonei?","Intraperitoneal accumulation of mucinous material, usually from appendiceal tumor (or ovarian).","Mucina no peritônio."],["1mf8mqg1h","What is a Brenner tumor?","Benign ovarian tumor resembling bladder epithelium (transitional cells) with coffee bean nuclei.","Tumor de Brenner."],["15xoepy8g","What is endometrioid ovarian carcinoma associated with?","Endometriosis and endometrial carcinoma.","Endometriose."],["18mne64rq","What is clear cell ovarian carcinoma associated with?","Endometriosis; hobnail cells.","Endometriose."],["1nvoomrbd","What is a mature cystic teratoma (dermoid cyst)?","Most common ovarian germ cell tumor (and most common ovarian tumor in young women): benign, contains elements from all three germ layers (teeth, hair, sebum); risk of torsion.","Teratoma maduro com dentes e cabelos."],["p5aezwyp5","What is struma ovarii?","Teratoma with functional thyroid tissue causing hyperthyroidism.","Teratoma com tireoide."],["16acvi5yi","What is dysgerminoma?","Malignant germ cell tumor (female counterpart of seminoma); sheets of fried egg cells; increased LDH and hCG; radiosensitive.","Equivalente feminino do seminoma."],["1t97tqz10","What is yolk sac (endodermal sinus) tumor?","Aggressive germ cell tumor in children and young women; Schiller-Duval bodies (resemble glomeruli); increased AFP.","Tumor do saco vitelino; AFP."],["rb4lam1rw","What is choriocarcinoma of the ovary?","Germ cell tumor with high hCG; can cause theca lutein cysts.","Coriocarcinoma; hCG alto."],["s5xyxu10z","What is a granulosa cell tumor?","Most common malignant sex cord stromal tumor: estrogen production (precocious puberty, endometrial hyperplasia, abnormal bleeding); Call-Exner bodies; inhibin elevated.","Produz estrogênio; corpos de Call-Exner."],["1t8g2q91x","What is a Sertoli-Leydig cell tumor?","Sex cord stromal tumor producing androgens (virilization, hirsutism); Reinke crystals.","Produz androgênios."],["14ss28vz7","What is a fibroma of the ovary and Meigs syndrome?","Benign fibroblast tumor; Meigs syndrome: ovarian fibroma, ascites, pleural effusion (resolves after removal).","Fibroma com ascite e derrame."],["14azp5wat","What is a Krukenberg tumor?","Metastatic gastric signet ring cell adenocarcinoma to ovaries (bilateral, mucin-secreting).","Metástase gástrica no ovário."],["suggfrxrd","What is vulvar carcinoma?","Usually squamous cell carcinoma; HPV-related in younger women (VIN), lichen sclerosus-related in older women.","Câncer de vulva."],["6n6r4l2y0","What is extramammary Paget disease of the vulva?","Intraepithelial adenocarcinoma: pruritic red crusted lesion; usually not associated with underlying carcinoma.","Doença de Paget vulvar."],["1elun0r1s","What is vaginal clear cell adenocarcinoma associated with?","In utero exposure to diethylstilbestrol (DES).","Exposição ao DES."],["1r7ng241n","What is sarcoma botryoides?","Embryonal rhabdomyosarcoma of vagina in girls <4: grape-like mass; desmin positive.","Massa em cacho de uva em meninas."],["15nn3fs1n","What is the most common breast cancer type?","Invasive ductal carcinoma.","Carcinoma ductal invasivo."],["82e8lnb7h","What are risk factors for breast cancer?","Female sex, age, BRCA1/2, early menarche, late menopause, nulliparity, late first pregnancy, obesity (postmenopausal), alcohol, radiation, family history, atypical hyperplasia.","Fatores de risco do câncer de mama."],["k4mnz81xk","What is the most common location of breast cancer?","Upper outer quadrant.","Quadrante superior externo."],["s8hy6g1fo","What are the most important prognostic factors in breast cancer?","Metastases, lymph node involvement, tumor size, hormone receptor and HER2 status.","Metástases, linfonodos e tamanho."],["1p3ewy2ui","What is ductal carcinoma in situ?","Malignant cells within ducts without basement membrane invasion; microcalcifications on mammography; comedo necrosis subtype.","Carcinoma ductal in situ."],["ngqgtes2s","What is Paget disease of the breast?","Eczematous patches on nipple from DCIS or invasive carcinoma extending to the nipple skin.","Eczema do mamilo."],["so4yketol","What is lobular carcinoma in situ (LCIS)?","Increased risk marker for invasive cancer in either breast; E-cadherin loss; incidental finding.","Marcador de risco."],["730j5b1l5","What is invasive lobular carcinoma?","Single-file (Indian file) cells, E-cadherin loss, often bilateral and multicentric; poorly seen on mammogram.","Células em fila indiana."],["1sxnhek1p","What is inflammatory breast cancer?","Dermal lymphatic invasion: peau d'orange, red warm swollen breast; poor prognosis; mimics mastitis.","Pele em casca de laranja."],["92nfy5p4d","What is medullary breast carcinoma?","Large anaplastic cells with lymphocytic infiltrate; associated with BRCA1; triple negative often.","Medular; BRCA1."],["1awj0441l","What is mucinous (colloid) breast carcinoma?","Abundant extracellular mucin; older women; good prognosis.","Mucinoso; bom prognóstico."],["146tmbrie","What is tubular breast carcinoma?","Well-differentiated tubules; excellent prognosis.","Tubular; ótimo prognóstico."],["o3l0k91qq","What is triple-negative breast cancer?","ER-, PR-, HER2-; aggressive; more common in young Black women and BRCA1 carriers.","Triplo negativo agressivo."],["1acif5j1n","What is the role of HER2 status?","HER2+ tumors are aggressive but respond to trastuzumab.","HER2+ responde ao trastuzumabe."],["1p9gswyz2","What are the breast cancer screening recommendations?","Mammography every 2 years starting at age 40 (USPSTF), earlier for high risk; MRI for BRCA carriers.","Mamografia a cada 2 anos após 40."],["3bqx5i1y7","What is male breast cancer associated with?","BRCA2, Klinefelter syndrome.","BRCA2 e Klinefelter."],["14suvi41q","What is the most common testicular tumor?","Germ cell tumors (seminoma most common).","Tumores de células germinativas."],["py68b9id0","What is seminoma?","Malignant germ cell tumor in men 15-35: painless homogeneous testicular enlargement; fried egg cells; radiosensitive; good prognosis; placental ALP.","Seminoma; radiossensível."],["1x605g0rt","What is embryonal carcinoma?","Malignant, hemorrhagic germ cell tumor with necrosis; painful; may have increased hCG and AFP.","Carcinoma embrionário."],["d1yipzjgb","What is yolk sac tumor of the testis?","Most common testicular tumor in boys <3; Schiller-Duval bodies; increased AFP.","Tumor do saco vitelino."],["1bj61x7tk","What is testicular choriocarcinoma?","Malignant cytotrophoblasts and syncytiotrophoblasts; hematogenous spread; increased hCG (gynecomastia, hyperthyroidism).","Coriocarcinoma testicular."],["60w5slj4k","What is testicular teratoma in adults?","Malignant in adult males (unlike ovarian teratoma).","Teratoma maligno no homem adulto."],["490l6u101","What is a Leydig cell tumor?","Non-germ cell tumor producing androgens or estrogens: gynecomastia in men, precocious puberty in boys; Reinke crystals.","Produz hormônios; cristais de Reinke."],["1fez80615","What is a Sertoli cell tumor?","Non-germ cell tumor, usually benign, androblastoma.","Tumor de Sertoli."],["1arbiv3ib","What is testicular lymphoma?","Most common testicular cancer in men >60; usually diffuse large B-cell lymphoma, often bilateral.","Linfoma em idosos."],["nj57enqg3","Why should testicular masses not be biopsied transscrotally?","Risk of seeding; treated with radical inguinal orchiectomy.","Orquiectomia inguinal."],["j17hfe13y","What is the lymphatic spread of testicular cancer?","Para-aortic lymph nodes.","Para-aórticos."],["h632eeaom","What is prostate adenocarcinoma?","Common in men >50; arises in posterior peripheral zone; increased PSA; osteoblastic bone metastases (lumbar spine).","Câncer de próstata; metástases osteoblásticas."],["cqfow675x","What is the screening for prostate cancer?","Shared decision-making for PSA in men 55-69.","Decisão compartilhada sobre PSA."],["yvmhzanxc","What is the Gleason score?","Grading based on glandular architecture; higher is more aggressive.","Graduação histológica."],["x5gaz41r9","Treatment of metastatic prostate cancer?","Androgen deprivation (GnRH agonists or antagonists, antiandrogens), abiraterone, enzalutamide, chemotherapy.","Bloqueio androgênico."],["1374lhmpg","What is squamous cell carcinoma of the penis associated with?","HPV, lack of circumcision, phimosis, smoking.","HPV e falta de circuncisão."],["1xkgpomeg","What is Bowen disease of the penis?","Squamous cell carcinoma in situ on the penile shaft or scrotum (gray, solitary plaque).","Carcinoma in situ."],["32zc511h0","What is erythroplasia of Queyrat?","Squamous cell carcinoma in situ on the glans (red velvety plaque).","Placa vermelha na glande."],["1sv7kzgba","What is the most common cause of a painless testicular mass in young men?","Testicular germ cell tumor (seminoma).","Tumor de células germinativas."],["106t52qvj","What is the role of AFP and beta-hCG in testicular tumors?","Tumor markers for diagnosis and monitoring; AFP elevated rules out pure seminoma.","Marcadores tumorais."],["1he5f251g","What is the BRCA1-associated cancer pattern?","Breast (triple negative), ovarian, prostate, pancreatic.","Mama e ovário."],["1mz4o9qu5","What is the BRCA2-associated cancer pattern?","Breast (including male), ovarian, prostate, pancreatic, melanoma.","Mama masculina e próstata."],["86bgct13r","What is prophylactic surgery for BRCA carriers?","Risk-reducing bilateral salpingo-oophorectomy (after childbearing) and mastectomy.","Cirurgia redutora de risco."],["1sb6nk01r","What is the most common site of breast cancer metastasis?","Bone, then liver, lung, brain.","Osso."],["eqlqv21ef","What is the role of sentinel lymph node biopsy in breast cancer?","Stages the axilla, avoiding full dissection if negative.","Estadia a axila."],["7sg81woi6","What is the treatment of ER-positive breast cancer?","Surgery, radiation, endocrine therapy (tamoxifen in premenopausal; aromatase inhibitors in postmenopausal).","Hormonioterapia."],["2yftm81yp","What is the triad of Meigs syndrome?","Ovarian fibroma, ascites, right pleural effusion.","Fibroma, ascite e derrame pleural."],["1xgdoizqw","What is the triple screening for a palpable breast mass?","Clinical exam, imaging, and tissue biopsy.","Exame, imagem e biópsia."],["j8cjy0hc9","What is a radial scar of the breast?","Benign lesion with central fibrosis mimicking carcinoma on mammography (stellate).","Lesão benigna estrelada."],["1re413pyg","What is sclerosing adenosis?","Benign proliferation of lobules with fibrosis and calcifications; slightly increased cancer risk.","Adenose esclerosante."],["1e3d6zlvt","What is atypical ductal hyperplasia's significance?","Increased risk of invasive breast cancer (about 4-5 times).","Risco aumentado de câncer."],["v847ca1of","What is the most common cause of bloody nipple discharge?","Intraductal papilloma.","Papiloma intraductal."],["yxbv4db8d","What is galactorrhea's common cause?","Prolactinoma, pregnancy, drugs (antipsychotics, metoclopramide), hypothyroidism.","Prolactinoma e drogas."],["kthb2giow","What is the most common gynecologic cancer death?","Ovarian cancer (usually diagnosed late).","Câncer de ovário."],["c4gxhl1hv","What is the most common gynecologic cancer worldwide?","Cervical cancer (developing countries).","Câncer do colo do útero."],["1qrnrnh4r","What is the Sister Mary Joseph nodule associated with in gynecology?","Ovarian cancer metastasis to umbilicus (also gastric).","Metástase umbilical."],["q30946bo3","What is the presentation of advanced ovarian cancer?","Bloating, abdominal distension (ascites), early satiety, pelvic mass.","Distensão e ascite."],["1v8ye661p","What is the role of CA-125 in endometriosis and other conditions?","Can be elevated in endometriosis, PID, pregnancy, fibroids; not specific.","Inespecífico."],["w6cbjwzvt","What is a fallopian tube carcinoma's typical presentation?","Watery vaginal discharge, pelvic pain, pelvic mass (rare).","Corrimento aquoso e massa."],["1fv9y9q1f","What is the role of HPV in oropharyngeal cancer vs cervical?","HPV-16 causes both; oropharyngeal HPV cancers have better prognosis.","HPV-16 em ambos."],["1lt9k5z17","What is the role of mammographic microcalcifications?","May indicate DCIS or early invasive carcinoma.","Podem indicar câncer inicial."]]},{"name":"Pharmacology","cards":[["11lg1ly11","Mechanism of leuprolide (GnRH agonist)?","Pulsatile use stimulates; continuous use downregulates GnRH receptors, decreasing LH and FSH.","Uso contínuo suprime o eixo."],["14yeh921b","Uses of leuprolide?","Uterine fibroids, endometriosis, precocious puberty, prostate cancer (with flutamide initially), infertility (pulsatile).","Miomas, endometriose, câncer de próstata."],["177ub741j","Adverse effects of leuprolide?","Hypogonadism, decreased libido, erectile dysfunction, hot flashes, initial flare in prostate cancer.","Fogachos e piora inicial."],["1gf74601b","Mechanism and use of GnRH antagonists (degarelix, elagolix, relugolix)?","Immediate suppression of LH and FSH without flare; prostate cancer, endometriosis, fibroids.","Supressão sem efeito flare."],["fo9sq1va1","Mechanism of clomiphene?","SERM that antagonizes estrogen receptors in the hypothalamus, increasing GnRH, LH, FSH to induce ovulation.","Induz ovulação."],["zh01t81cf","Uses and adverse effects of clomiphene?","Infertility (PCOS); hot flashes, ovarian enlargement, multiple gestations, visual disturbances.","Infertilidade; gestação múltipla."],["716p44t00","Mechanism and use of letrozole for infertility?","Aromatase inhibitor reducing estrogen feedback, increasing FSH; first-line ovulation induction in PCOS.","Indução de ovulação na SOP."],["198123v1v","Mechanism and use of tamoxifen?","SERM: antagonist in breast, agonist in bone and endometrium; ER+ breast cancer treatment and prevention.","Antagonista na mama."],["2alfou1xz","Adverse effects of tamoxifen?","Endometrial cancer, thromboembolism, hot flashes.","Câncer de endométrio e trombose."],["1dl8iuh1n","Mechanism and use of raloxifene?","SERM: agonist in bone, antagonist in breast and uterus; osteoporosis and breast cancer prevention.","Osteoporose sem risco endometrial."],["4p8l3g1k0","Adverse effects of raloxifene?","Thromboembolism, hot flashes; no endometrial cancer increase.","Trombose."],["14rvcashn","Mechanism and use of aromatase inhibitors?","Anastrozole, letrozole, exemestane inhibit peripheral estrogen synthesis; ER+ breast cancer in postmenopausal women.","Câncer de mama pós-menopausa."],["1i55xqawz","Mechanism and use of fulvestrant?","Selective estrogen receptor degrader; metastatic ER+ breast cancer.","Degrada o receptor de estrogênio."],["1fhevgbsy","Mechanism and use of combined oral contraceptives?","Estrogen and progestin inhibit LH/FSH (prevent ovulation), progestin thickens cervical mucus and thins endometrium.","Inibem a ovulação."],["78k20cxc9","Benefits of combined oral contraceptives?","Reduce ovarian and endometrial cancer risk, dysmenorrhea, acne, menorrhagia, PCOS symptoms.","Reduzem câncer de ovário e endométrio."],["g1pxz76ma","Contraindications to estrogen-containing contraceptives?","Smokers >35, history of thromboembolism or stroke, migraine with aura, breast cancer, liver disease, uncontrolled hypertension, <3 weeks postpartum.","Fumante acima de 35, trombose, enxaqueca com aura."],["ibdsqt2t6","Adverse effects of estrogens?","Hypercoagulability (VTE), hypertension, endometrial hyperplasia if unopposed, breast tenderness, nausea, hepatic adenoma.","Trombose e hipertensão."],["18ssgyhq4","Mechanism and use of progestin-only contraception?","Thickens cervical mucus, may inhibit ovulation; safe in breastfeeding and when estrogen contraindicated (mini-pill, implant, Depo-Provera, levonorgestrel IUD).","Sem estrogênio."],["emsze1jyg","Adverse effects of medroxyprogesterone acetate injection?","Irregular bleeding, weight gain, decreased bone density, delayed return of fertility.","Perda óssea e retorno lento da fertilidade."],["1lsgqqa8s","Mechanism of the copper IUD?","Produces local inflammatory reaction toxic to sperm and ova; most effective emergency contraception.","DIU de cobre; contracepção de emergência."],["1a0khty1g","Adverse effects of copper IUD?","Heavier menses, dysmenorrhea; small risk of PID at insertion.","Menstruação mais intensa."],["1uz3ah9no","Mechanism of levonorgestrel IUD?","Local progestin: thickens cervical mucus, thins endometrium; reduces menstrual bleeding.","DIU hormonal reduz sangramento."],["1twux0wmt","What are emergency contraception options?","Copper IUD (most effective, up to 5 days), ulipristal (up to 5 days), levonorgestrel (best within 72 hours).","DIU de cobre, ulipristal, levonorgestrel."],["upbkhb9aa","Mechanism and use of mifepristone?","Progesterone receptor antagonist; medical abortion (with misoprostol), Cushing syndrome.","Antagonista da progesterona; aborto."],["9o3k6tfez","Mechanism and use of misoprostol in obstetrics?","PGE1 analog: cervical ripening, labor induction, medical abortion, postpartum hemorrhage.","Prostaglandina; indução e hemorragia."],["15uhc2q1a","Mechanism and use of dinoprostone?","PGE2 analog for cervical ripening.","Prostaglandina E2."],["wve8s1c1q","Mechanism and use of oxytocin?","Stimulates uterine contractions; labor induction and augmentation, postpartum hemorrhage control.","Contrações uterinas."],["9jnqnftke","Mechanism and use of methylergonovine?","Ergot alkaloid causing uterine contraction; postpartum hemorrhage; contraindicated in hypertension.","Ergot; evitar na hipertensão."],["eildcn1qt","Mechanism and use of carboprost?","PGF2-alpha analog causing uterine contraction; postpartum hemorrhage; contraindicated in asthma.","Evitar na asma."],["i8eevemjk","Mechanism and use of tranexamic acid in obstetrics?","Antifibrinolytic reducing postpartum hemorrhage mortality (give within 3 hours).","Reduz mortalidade por hemorragia."],["a6rds71yl","Mechanism of tocolytics?","Nifedipine (CCB), indomethacin (NSAID, <32 weeks), terbutaline (beta2 agonist), magnesium sulfate: relax uterine contractions to delay preterm labor.","Inibem contrações."],["4okr6xdbj","Why is indomethacin limited to <32 weeks as a tocolytic?","Risk of premature ductus arteriosus closure and oligohydramnios.","Fecha o ducto arterioso."],["774cks1dn","Mechanism and use of betamethasone in preterm labor?","Accelerates fetal lung maturity (surfactant) between 24-34 weeks.","Maturação pulmonar fetal."],["1ifptbd1y","Mechanism and use of magnesium sulfate in obstetrics?","Seizure prophylaxis in preeclampsia, eclampsia treatment, fetal neuroprotection <32 weeks.","Previne convulsões."],["1c31e7fu7","Which antihypertensives are used in pregnancy?","Labetalol, nifedipine, methyldopa, hydralazine.","Labetalol, nifedipino, metildopa."],["1wvaogk1u","Which antihypertensives are contraindicated in pregnancy?","ACE inhibitors, ARBs, aliskiren (fetal renal toxicity).","IECA e BRA."],["6swrx831b","Which anticoagulant is used in pregnancy?","Low-molecular-weight heparin.","Heparina de baixo peso."],["1k6jxeqtz","Which antibiotics are avoided in pregnancy?","Tetracyclines, fluoroquinolones, aminoglycosides, sulfonamides (near term), metronidazole (first trimester caution), clarithromycin.","Tetraciclinas e quinolonas."],["hcp3bi1jk","Which antiepileptic is most teratogenic?","Valproate.","Valproato."],["vf5onsl4d","Which thyroid drug is used in the first trimester?","Propylthiouracil (methimazole later).","Propiltiouracil."],["16efzpm1m","Mechanism and use of testosterone and methyltestosterone?","Androgen receptor agonists; hypogonadism, promote secondary sex characteristics, anemia of renal failure (historically).","Reposição de testosterona."],["1mh6vq79t","Adverse effects of exogenous testosterone?","Masculinization in women, testicular atrophy and infertility in men (LH/FSH suppression), polycythemia, acne, edema, increased LDL, decreased HDL.","Atrofia testicular e policitemia."],["3l0cig3au","Mechanism and use of finasteride?","5-alpha-reductase inhibitor decreasing DHT; BPH, male pattern baldness.","Hiperplasia prostática e calvície."],["i8ir8d1uw","Adverse effects of finasteride?","Decreased libido, erectile dysfunction, gynecomastia; teratogenic to male fetus (pregnant women should not handle).","Disfunção sexual; teratogênico."],["5bq3s41tg","Mechanism and use of flutamide and bicalutamide?","Nonsteroidal competitive androgen receptor antagonists; prostate carcinoma.","Antiandrogênicos; câncer de próstata."],["16scfbf1e","Mechanism and use of enzalutamide and apalutamide?","Second-generation androgen receptor inhibitors; castration-resistant prostate cancer.","Antiandrogênicos de nova geração."],["186565adn","Mechanism and use of abiraterone?","CYP17A1 (17-alpha-hydroxylase) inhibitor decreasing androgen synthesis; metastatic prostate cancer; given with prednisone.","Inibe síntese de androgênios."],["1mjhzs88m","Mechanism of ketoconazole and spironolactone as antiandrogens?","Ketoconazole inhibits steroid synthesis (17,20-desmolase); spironolactone blocks androgen receptor and inhibits steroid synthesis; used for PCOS hirsutism.","Tratam hirsutismo."],["xf8g0j11x","Mechanism and use of PDE5 inhibitors?","Sildenafil, tadalafil, vardenafil increase cGMP; erectile dysfunction, pulmonary hypertension, BPH (tadalafil).","Disfunção erétil."],["6i647q1qh","Adverse effects of PDE5 inhibitors?","Headache, flushing, dyspepsia, cyanopia (blue vision), hearing loss; hypotension with nitrates.","Hipotensão com nitratos."],["1yot2xf14","Mechanism and use of danazol?","Synthetic androgen and partial agonist at androgen receptors; endometriosis, hereditary angioedema.","Endometriose e angioedema hereditário."],["1g1i8lyy7","Adverse effects of danazol?","Weight gain, edema, acne, hirsutism, masculinization, low HDL, hepatotoxicity, idiopathic intracranial hypertension.","Virilização."],["1jl0crwnk","Mechanism and use of menopausal hormone therapy?","Estrogen (with progestin if uterus present) for vasomotor symptoms and vaginal atrophy; lowest dose shortest duration.","Reposição hormonal da menopausa."],["bh2ruw1y1","Why is progestin added to estrogen therapy in women with a uterus?","Prevents endometrial hyperplasia and cancer.","Protege o endométrio."],["1fpap1m18","Risks of combined menopausal hormone therapy?","Breast cancer, VTE, stroke, coronary disease (in older women), gallbladder disease.","Câncer de mama, trombose, AVC."],["pp6frt1xw","Nonhormonal treatment of hot flashes?","SSRIs/SNRIs (paroxetine, venlafaxine), gabapentin, clonidine, fezolinetant (neurokinin 3 receptor antagonist).","Paroxetina, venlafaxina, fezolinetante."],["1ig58x111","Mechanism and use of ospemifene?","SERM for dyspareunia from vulvovaginal atrophy.","Dispareunia da menopausa."],["qli9arf2p","Mechanism and use of cabergoline in reproductive disorders?","Dopamine agonist; hyperprolactinemia, lactation suppression.","Hiperprolactinemia."],["1l388zcqc","Mechanism and use of terbutaline in obstetrics?","Beta2 agonist for short-term tocolysis (not prolonged due to maternal cardiac effects).","Tocolítico de curto prazo."],["m883qg15z","Mechanism and use of hCG in infertility?","Mimics LH surge to trigger ovulation.","Dispara a ovulação."],["88gii213v","Mechanism and use of recombinant FSH (follitropin)?","Stimulates follicle development in IVF and ovulation induction.","Estimula folículos."],["2q6y3rscx","Mechanism and use of methotrexate in obstetrics?","Folate antagonist for ectopic pregnancy and medical abortion; gestational trophoblastic disease.","Gravidez ectópica."],["5eekp4qf0","What are contraindications to methotrexate for ectopic pregnancy?","Rupture or hemodynamic instability, fetal cardiac activity, large mass, breastfeeding, liver or renal disease.","Ruptura e instabilidade."],["asr5cucm0","Mechanism and use of anti-D immunoglobulin?","Prevents maternal sensitization to fetal Rh antigens.","Previne aloimunização Rh."],["k7sw2u9zh","Which vitamin supplement prevents neural tube defects?","Folic acid (0.4 mg daily; 4 mg if prior NTD).","Ácido fólico."],["1vchjud8s","Mechanism and use of zuranolone?","Oral neurosteroid (GABA-A modulator) for postpartum depression.","Depressão pós-parto."],["1y2301xag","What antidepressant is safest in breastfeeding?","Sertraline (and paroxetine).","Sertralina."],["1wpxkyjpt","Which drug is used to suppress lactation if necessary?","Cabergoline (bromocriptine historically).","Cabergolina."],["c2n6qlq4j","Which drug treats bacterial vaginosis and trichomoniasis?","Metronidazole.","Metronidazol."],["h4cdbi1hx","Which drug treats vulvovaginal candidiasis?","Fluconazole or topical azoles.","Fluconazol."],["1y22gaf10","Which drug treats syphilis in pregnancy?","Penicillin G (desensitize if allergic).","Penicilina G."],["1seuwqu7t","Which drug treats PID outpatient?","Ceftriaxone IM plus doxycycline plus metronidazole.","Ceftriaxona, doxiciclina e metronidazol."],["1yy93a71v","Which drug is used for GBS prophylaxis intrapartum?","Penicillin G or ampicillin (cefazolin if low-risk penicillin allergy).","Penicilina G."],["cr2lywk8m","Which drug class reduces menstrual bleeding in heavy menses?","NSAIDs, tranexamic acid, hormonal contraceptives, levonorgestrel IUD.","Ácido tranexâmico e DIU hormonal."],["qu2zlt1fp","Which drug treats primary dysmenorrhea?","NSAIDs (and hormonal contraceptives).","AINEs."],["1av5doi11","Which drug treats PCOS-related insulin resistance?","Metformin.","Metformina."]]},{"name":"Physiology","cards":[["1ierkso14","What are the phases of the menstrual cycle?","Follicular phase (variable, estrogen rises), ovulation (LH surge, day 14), luteal phase (fixed 14 days, progesterone).","Folicular, ovulação, lútea."],["5f199s1pm","What triggers the LH surge?","Rising estrogen causing positive feedback on LH secretion.","Estrogênio alto."],["1gkbqf6im","What is the effect of FSH in females?","Stimulates follicle growth and granulosa cell aromatase activity.","Crescimento folicular."],["1unc7nf1y","What is the effect of LH in females?","Stimulates theca cell androgen production, ovulation, and corpus luteum.","Ovulação e corpo lúteo."],["1w6vuxt1r","What is the role of progesterone in the luteal phase?","Converts proliferative endometrium to secretory, increases body temperature, thickens cervical mucus, maintains pregnancy.","Endométrio secretor."],["uwolb81j7","What happens to the endometrium in the follicular phase?","Proliferation of glands under estrogen.","Proliferação."],["oxbl091nh","What causes menstruation?","Decline in progesterone (corpus luteum involution) causing endometrial sloughing.","Queda da progesterona."],["16yppgwn1","Which phase length is constant?","Luteal phase (14 days); variability in cycle length is due to the follicular phase.","Fase lútea fixa."],["lj6lb3246","What is mittelschmerz?","Midcycle pelvic pain at ovulation from follicular rupture.","Dor da ovulação."],["u3n9p81ot","What is the basal body temperature change at ovulation?","Rises after ovulation (progesterone).","Temperatura sobe após ovular."],["1i328apte","What are the effects of estrogen?","Development of genitalia and breast, female fat distribution, follicle growth, endometrial proliferation, increased transport proteins (SHBG, TBG), increased HDL, decreased LDL, hypercoagulability.","Efeitos do estrogênio."],["hgxtpldak","What are the effects of progesterone?","Endometrial secretory changes, thick cervical mucus, increased body temperature, uterine relaxation, decreased estrogen receptors, pregnancy maintenance.","Efeitos da progesterona."],["1qu37vh1a","What is the main estrogen in reproductive years, pregnancy, and menopause?","Estradiol (reproductive), estriol (pregnancy, placenta), estrone (menopause, adipose).","Estradiol, estriol, estrona."],["1pllt33k1","What are the effects of testosterone?","Differentiation of epididymis, vas deferens, seminal vesicles; growth spurt, penis growth, spermatogenesis, deepening voice, libido, muscle mass.","Efeitos da testosterona."],["7uea0aue7","What are the effects of DHT?","Early: differentiation of penis, scrotum, prostate. Late: prostate growth, male pattern baldness, sebaceous glands.","Genitália externa e próstata."],["1ixe2531x","What regulates testosterone?","GnRH stimulates LH, which stimulates Leydig cells; testosterone inhibits GnRH and LH (negative feedback).","Eixo hipotálamo-hipófise-gônada."],["1kpftixo5","What regulates spermatogenesis?","FSH stimulates Sertoli cells; inhibin B gives negative feedback on FSH.","FSH e inibina."],["s59xqjdh7","Why do exogenous androgens cause infertility?","Suppress LH and FSH (negative feedback), decreasing intratesticular testosterone and spermatogenesis; testicular atrophy.","Suprimem LH e FSH."],["u2amo5czv","How long does spermatogenesis take?","About 2 months (64 days).","Cerca de 64 dias."],["1qvdztu19","What are the stages of spermatogenesis?","Spermatogonium (2N, 4C after replication), primary spermatocyte (meiosis I), secondary spermatocyte (meiosis II), spermatid, spermatozoon (spermiogenesis).","Etapas da espermatogênese."],["1al9ie913","What are the stages of oogenesis?","Primary oocytes arrested in prophase I until ovulation; secondary oocyte arrested in metaphase II until fertilization.","Etapas da ovogênese."],["1rxuxel72","What is the role of hCG in early pregnancy?","Maintains corpus luteum progesterone production during first trimester; detectable ~8 days after fertilization.","Mantém o corpo lúteo."],["1uv8khys7","What are the physiologic changes of pregnancy in the cardiovascular system?","Increased CO (stroke volume and HR), increased blood volume, decreased SVR and BP (second trimester), dilutional anemia.","Débito aumenta e pressão cai."],["159b0931l","What are the physiologic changes of pregnancy in the respiratory system?","Increased tidal volume and minute ventilation (progesterone), respiratory alkalosis with renal compensation, decreased FRC.","Hiperventilação e alcalose respiratória."],["jjqe5kffp","What are the physiologic changes of pregnancy in the kidney?","Increased GFR and RPF, decreased BUN and creatinine, glucosuria, hydronephrosis (right).","Filtração aumenta."],["14oib8rso","What are the physiologic changes of pregnancy in coagulation?","Hypercoagulable state (increased fibrinogen and factors).","Estado de hipercoagulabilidade."],["2m6tnt7f7","What are the physiologic changes of pregnancy in the thyroid?","Increased TBG (estrogen), increased total T4, hCG stimulates TSH receptor (low TSH in first trimester).","TBG aumenta."],["1uz8qve1c","What are the physiologic changes of pregnancy in glucose metabolism?","Insulin resistance from hPL, cortisol, progesterone (gestational diabetes).","Resistência à insulina."],["rdhi76v6d","What are the physiologic changes of pregnancy in the GI tract?","Decreased motility (progesterone), GERD, constipation, gallstones.","Refluxo e constipação."],["oxivry19c","What is the role of prolactin in lactation?","Stimulates milk production; suppressed by high estrogen and progesterone in pregnancy; rises after delivery.","Produção de leite."],["ynrpwf16c","What is the role of oxytocin in lactation?","Milk letdown via myoepithelial contraction (suckling reflex).","Ejeção do leite."],["19g43uknj","Why does breastfeeding suppress ovulation?","Prolactin inhibits GnRH.","Prolactina inibe GnRH."],["802n9e15h","What are the benefits of breast milk?","IgA, macrophages, lymphocytes, lactoferrin; reduces infections, obesity, diabetes, SIDS; supplement vitamin D (and iron after 4-6 months).","Benefícios do leite materno."],["onwuz918k","What vitamin must be supplemented in exclusively breastfed infants?","Vitamin D.","Vitamina D."],["ircss11k9","What is menopause?","Cessation of menses for 12 months due to loss of ovarian follicles (average age 51).","12 meses sem menstruação."],["1x410312t","What hormone changes occur in menopause?","Decreased estrogen, very high FSH (best test), high LH, decreased inhibin, increased GnRH.","FSH muito alto."],["1gof9svv6","What are the symptoms of menopause?","Hot flashes, atrophy of vagina, osteoporosis, coronary artery disease risk, sleep disturbances, mood changes (HAVOCS).","Fogachos, atrofia, osteoporose."],["4ymmm1bpp","What is primary ovarian insufficiency?","Menopause before age 40 (Turner syndrome, autoimmune, chemotherapy, fragile X premutation).","Menopausa antes dos 40."],["i4zxu6wwl","What is andropause?","Gradual decrease in testosterone with age; erectile dysfunction, decreased libido.","Queda gradual da testosterona."],["3dl75culg","What is the order of female puberty events?","Thelarche, pubarche, growth spurt, menarche.","Mamas, pelos, estirão, menarca."],["1k7z0vn1w","What is the order of male puberty events?","Testicular enlargement, pubarche, growth spurt (later than girls).","Testículos, pelos, estirão."],["y3a6rf191","What is the function of inhibin?","Inhibits FSH (Sertoli cells in males, granulosa cells in females).","Inibe FSH."],["1kee7xy17","What is the function of activin?","Stimulates FSH.","Estimula FSH."],["1av74x2ty","What is the function of SHBG?","Binds testosterone and estrogen; increased by estrogen and hyperthyroidism, decreased by androgens, obesity, insulin.","Liga hormônios sexuais."],["v8ewwss1n","What is the role of aromatase in men?","Converts testosterone to estradiol in adipose tissue; obesity increases estrogen (gynecomastia).","Converte testosterona em estrogênio."],["r5q4di1wp","What is the hormone profile of hypogonadotropic hypogonadism?","Low LH and FSH, low sex steroids (Kallmann, hyperprolactinemia, anorexia).","LH e FSH baixos."],["pxrbku1fp","What is the hormone profile of hypergonadotropic hypogonadism?","High LH and FSH, low sex steroids (Klinefelter, Turner, menopause).","LH e FSH altos."],["1ow043s71","What is the hormone profile of androgen insensitivity syndrome?","High testosterone, high estrogen, high LH (resistance).","Testosterona e LH altos."],["basype1wp","What is the hormone profile of 5-alpha reductase deficiency?","Normal testosterone, low DHT, normal or high LH.","DHT baixa."],["1b9jq331r","What is the hormone profile of exogenous anabolic steroid use in men?","Low LH and FSH, testicular atrophy, low sperm count, high hematocrit.","LH e FSH baixos; atrofia testicular."],["olb23mgjq","What is the hormone profile of PCOS?","High LH:FSH ratio, high androgens, insulin resistance.","LH/FSH alta e androgênios altos."],["jggx91p0b","What hormones are produced by the placenta?","hCG, hPL, estriol, progesterone, CRH.","Hormônios placentários."],["2ceh4q1dl","What is the role of hPL?","Increases maternal insulin resistance and lipolysis to provide fetal glucose; promotes breast development.","Resistência à insulina materna."],["p1jnrrms4","What is the role of relaxin in pregnancy?","Relaxes pelvic ligaments and softens the cervix.","Relaxa ligamentos."],["4xef7611s","What initiates labor?","Increased oxytocin receptors, prostaglandins, fetal cortisol, uterine stretch (positive feedback).","Ocitocina e prostaglandinas."],["1jowx0z1e","What are the stages of labor?","First: onset to full dilation (latent, active). Second: full dilation to delivery of baby. Third: delivery of placenta.","Estágios do trabalho de parto."],["1p39hte1i","What is the normal fetal heart rate?","110-160 bpm.","110 a 160 bpm."],["1a6svkj1k","What do early decelerations indicate?","Head compression (benign), mirroring contractions.","Compressão da cabeça."],["1gqd2ra8i","What do variable decelerations indicate?","Umbilical cord compression.","Compressão do cordão."],["1u6fkc1kj","What do late decelerations indicate?","Uteroplacental insufficiency (fetal hypoxia).","Insuficiência placentária."],["1ophivuhp","What is the role of the Apgar score?","Assesses newborn at 1 and 5 minutes.","Avaliação do recém-nascido."],["2mtoev1v5","What is the hormone responsible for erectile function?","Nitric oxide (increases cGMP, smooth muscle relaxation).","Óxido nítrico."],["1yiop63fw","What causes erectile dysfunction?","Vascular (atherosclerosis), neurologic (diabetes), hormonal, drugs (antihypertensives, SSRIs), psychological.","Vascular, neurológica, drogas."],["1e1ybuq13","What is the normal semen analysis?","Volume ≥1.5 mL, concentration ≥15 million/mL, motility ≥40%, normal morphology ≥4%.","Espermograma normal."],["1l4c1leub","What is the most common cause of male infertility that is correctable?","Varicocele.","Varicocele."],["ciozd3fgp","What is the cause of infertility in cystic fibrosis males?","Congenital bilateral absence of the vas deferens (obstructive azoospermia).","Ausência dos ductos deferentes."],["4xho83sne","What is the test for ovulation?","Mid-luteal (day 21) progesterone level.","Progesterona no 21º dia."],["152wv2q1n","What is the test for ovarian reserve?","Anti-Müllerian hormone (and day 3 FSH, antral follicle count).","Hormônio antimülleriano."],["19p0jhx1g","What is the hysterosalpingography used for?","Assess tubal patency and uterine cavity in infertility.","Avalia trompas e útero."],["b1vkwnpia","What is the difference between primary and secondary amenorrhea?","Primary: no menses by age 15 (or 13 without secondary sex characteristics). Secondary: absence of menses for 3 months (regular) or 6 months (irregular).","Primária e secundária."],["1yhairq1v","What is the first test in secondary amenorrhea?","Pregnancy test (beta-hCG).","Teste de gravidez."],["1wpk8zt1u","What is the progestin challenge test?","Withdrawal bleeding indicates adequate estrogen and patent outflow tract.","Sangramento indica estrogênio adequado."],["1fhai2nhe","What causes hypothalamic amenorrhea?","Stress, excessive exercise, weight loss (female athlete triad), anorexia: low GnRH.","Estresse, exercício e baixo peso."],["1ptrp614a","What is the female athlete triad?","Low energy availability, menstrual dysfunction, low bone mineral density.","Baixa energia, amenorreia e osteoporose."],["bqas7f1uu","What is the cause of galactorrhea and amenorrhea?","Hyperprolactinemia (prolactinoma, dopamine antagonists, hypothyroidism).","Hiperprolactinemia."],["1my94k0qk","What is Asherman syndrome?","Intrauterine adhesions after D&C or infection causing secondary amenorrhea.","Aderências intrauterinas."],["15h785n10","What is the purpose of the cervical mucus change at ovulation?","Thin, watery, stretchy (spinnbarkeit) mucus facilitates sperm passage (estrogen).","Muco fino facilita os espermatozoides."],["323gz8tiu","What is the purpose of capacitation?","Final sperm maturation in female tract enabling fertilization.","Maturação final do espermatozoide."],["n8vphjnyy","What prevents polyspermy?","Cortical reaction modifying the zona pellucida.","Reação cortical."],["suawxc4dg","What is implantation's timing?","About 6 days after fertilization.","Cerca de 6 dias."],["eqfnbo1fo","When can hCG be detected in serum?","About 8 days after fertilization (doubles every 48 hours early).","Cerca de 8 dias."],["1qc9p8b13","What does inadequate hCG rise suggest?","Ectopic pregnancy or failing intrauterine pregnancy.","Gravidez ectópica ou perda."],["1atwbn1hu","At what hCG level should an intrauterine pregnancy be visible on transvaginal ultrasound?","About 1500-3500 mIU/mL (discriminatory zone).","Zona discriminatória."]]}];
